"""Threaded queue worker: pulls items and hands each to a callback."""

import logging
import queue
import threading

log = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Consumes items from a queue.Queue on a background thread."""

    def __init__(self, callback, work_queue=None, name="queue-worker"):
        self.callback = callback
        self.queue = work_queue if work_queue is not None else queue.Queue()
        self._thread = threading.Thread(target=self._run, name=name, daemon=True)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()

    def submit(self, item):
        self.queue.put(item)

    def _run(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.callback(item)
            except Exception:
                # One bad item must not kill the thread; the queue keeps draining.
                log.exception("callback failed for %r", item)
            finally:
                self.queue.task_done()

    def join_pending(self, timeout=None):
        """Block until everything queued so far has been processed."""
        self.queue.join()

    def stop(self, timeout=5.0):
        """Signal shutdown and wait for the thread to finish the current item."""
        if not self._started:
            return
        self.queue.put(_SHUTDOWN)
        self._thread.join(timeout)
        if self._thread.is_alive():
            log.warning("worker did not stop within %.1fs", timeout)

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
